```
To double check, I was able to verify that my home server could reach `matrix.org`:

```
server$ curl -v https://matrix.org/_matrix/client/versions 2>&1 | grep "Server:"
< Server: Synapse/0.26.0 (b=matrix-org-hotfixes,9249f11)
```

### Version information

- **Matrix.org-Version**: Synapse/0.26.0 (b=matrix-org-hotfixes,9249f11)
- **Homeserver-Version**:  Synapse/0.26.0
- **Install method**: NixOS option `services.matrix-synapse.enable = true;`
- **Platform**:  NixOS running on a virtual x86 server hosted by Scaleway.com

NixOS configuration snippet:

```nix
{
  services.matrix-synapse = {
    enable = true;
    server_name = "homeserver.com";
    registration_shared_secret = "secret";
    public_baseurl = "https://matrix.homeserver.com/";
    tls_certificate_path = "/var/lib/acme/matrix.homeserver.com/fullchain.pem";
    tls_private_key_path = "/var/lib/acme/matrix.homeserver.com/key.pem";
    database_type = "psycopg2";
    database_args = {
      database = "matrix-synapse";
    };
    turn_shared_secret = "secret";
    turn_uris = [
    "turn:turn.region.homeserver.com:5349?transport=udp"
    "turn:turn.region.homeserver.com:5350?transport=udp"
    "turn:turn.region.homeserver.com:5349?transport=tcp"
    "turn:turn.region.homeserver.com:5350?transport=tcp"
    ];
    listeners = [
      { # federation
        bind_address = "";
        port = 8448;
        resources = [
          { compress = true; names = [ "client" "webclient" ]; }
          { compress = false; names = [ "federation" ]; }
        ];
        tls = true;
        type = "http";
        x_forwarded = false;
      }
      { # client
        bind_address = "127.0.0.1";
        port = 8008;
        resources = [
          { compress = true; names = [ "client" "webclient" ]; }
        ];
        tls = false;
        type = "http";
        x_forwarded = true;
      }
    ];
  };


  # web client proxy and setup certs
  services.nginx = {
    enable = true;
    virtualHosts = {
      "matrix.homeserver.com" = {
        forceSSL = true;
        enableACME = true;
        locations."/" = {
          proxyPass = "http://127.0.0.1:8008";
        };
      };
    };
  };

  # share certs with matrix-synapse and restart on renewal
  security.acme.certs = {
    "matrix.homeserver.com" = {
      group = "matrix-synapse";
      allowKeysForGroup = true;
      postRun = "systemctl reload nginx.service; systemctl restart matrix-synapse.service";
    };
  };

  # Open ports in the firewall.
  networking.firewall = {
    enable = true;
    allowPing = false;
    allowedTCPPorts = [
      22    # SSH
      8448  # Matrix federation
      80    # http
      443   # https
    ];
  };
}
```
